CREATE POLICY "own food-scans read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'food-scans' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own food-scans insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'food-scans' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own food-scans delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'food-scans' AND (storage.foldername(name))[1] = auth.uid()::text);